mapper.select:
SELECT * FROM memorial 
WHERE type = #{type} 
ORDER BY date ASC

SELECT * FROM memorial 
WHERE type != #{type} 
ORDER BY date ASC

SELECT * FROM memorial 
WHERE date >= #{startDate} AND date <= #{endDate} 
ORDER BY date ASC

SELECT * FROM memorial 
WHERE MONTH(date) = #{month} 
ORDER BY DAY(date) ASC
